class RecLog                     # facade over IO, owning the descriptor
  def initialize(path)
    @io = File.open(path, 'a')
  end

  def append(line) = @io.write("#{line}\n")
  def close = @io.close unless @io.closed?
end

File.open('app.log', 'a') { |io| io.write("ready\n") }   # or block-scoped teardown

